"""Portable, escaped HTML with evidence available for every result."""

import html
import json
from pathlib import Path


def render_report(run: dict, comparison: dict | None = None) -> str:
    def esc(value):
        return html.escape(str(value), quote=True)

    summary = run["summary"]
    demo = run["adapter"].startswith("scripted-")
    cards = [("PASS RATE", f"{summary['pass_rate']:.0%}", f"{summary['passed']} / {summary['count']} executions passed"),
             ("CASES", len({r['case_id'] for r in run['results']}), f"{run['config']['repetitions']} repetition(s) per case"),
             ("P95 LATENCY", f"{summary['latency_p95_ms']:.1f} ms", "Wall time including retry backoff"),
             ("EXECUTION ERRORS", summary['errors'], "Timeouts and adapter/evaluator failures")]
    card_html = "".join(f'<article class="card"><span class="eyebrow">{esc(k)}</span><strong>{esc(v)}</strong><small>{esc(d)}</small></article>' for k, v, d in cards)
    slices = "".join(f'<div class="slice"><span>{esc(tag)}</span><div class="track"><div style="width:{data["pass_rate"]*100:.2f}%"></div></div><b>{data["passed"]}/{data["count"]}</b></div>' for tag, data in summary['slices'].items())
    compare_html = ""
    if comparison:
        compare_html = f'''<section class="panel comparison"><div><span class="eyebrow">PAIRED REGRESSION GATE</span><h2>{"Ready to proceed" if comparison['gate_passed'] else "Review required"}</h2><p>{len(comparison['improvements'])} improved executions · {len(comparison['regressions'])} regressions</p></div><div class="delta">{comparison['delta']*100:+.1f}<small>percentage points vs baseline</small></div><p class="wide">Baseline {comparison['baseline_pass_rate']:.1%} → candidate {comparison['candidate_pass_rate']:.1%}. Case-bootstrap 95% interval: [{comparison['delta_ci95'][0]*100:+.1f}, {comparison['delta_ci95'][1]*100:+.1f}] pp. {esc(', '.join(comparison['gate_reasons']) or 'All configured gates passed.')}</p></section>'''
    rows = []
    for r in run['results']:
        prediction = r['prediction']
        answer = prediction['answer'] if prediction else "No answer recorded"
        metrics = "".join(f'<li><span class="badge {"pass" if m["passed"] else "fail"}">{"PASS" if m["passed"] else "FAIL"}</span> <b>{esc(m["name"])}</b> · {m["score"]:.2f} / {m["threshold"]:.2f}<small>{esc(m["reason"])}</small></li>' for m in r['metrics'])
        trace = json.dumps(prediction['trace'] if prediction else [], ensure_ascii=False, indent=2)
        rows.append(f'''<details class="case" data-status="{"pass" if r['passed'] else "fail"}"><summary><span class="badge {"pass" if r['passed'] else "fail"}">{"PASS" if r['passed'] else "FAIL"}</span><b>{esc(r['case_id'])}</b><span class="tags">{esc(' / '.join(r['tags']))}</span><span>{r['latency_ms']:.1f} ms</span></summary><div class="evidence"><p class="eyebrow">ANSWER · REPETITION {r['repetition'] + 1} · {r['attempts']} ATTEMPT(S)</p><pre>{esc(answer)}</pre><ul>{metrics}</ul><p>Status: {esc(r['status'])} {esc(r['error_type'] or '')}</p><p class="eyebrow">TOOL TRACE</p><pre>{esc(trace)}</pre></div></details>''')
    known_cost = "Unknown / not applicable" if summary['known_success_cost_usd'] is None else f"${summary['known_success_cost_usd']:.6f} ({summary['cost_coverage']:.0%} coverage)"
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agent Eval Lab · {esc(run['adapter'])}</title><style>
:root{{--ink:#172b37;--muted:#586c78;--paper:#f4f5f1;--line:#dbe2dc;--green:#075e47;--gold:#e8b957}}*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font:15px/1.6 system-ui,sans-serif}}main{{max-width:1160px;margin:auto;padding:36px 28px 60px}}header{{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:20px}}.brand{{font-weight:800;letter-spacing:-.5px;font-size:20px}}.mark{{display:inline-grid;place-items:center;background:var(--ink);color:var(--gold);width:32px;height:32px;margin-right:10px;border-radius:8px}}.mono{{font:12px ui-monospace,monospace;color:var(--muted)}}.hero{{padding:44px 0 24px;max-width:850px}}.eyebrow{{font-size:11px;font-weight:750;letter-spacing:1.6px;color:var(--muted)}}h1{{font-size:clamp(32px,5vw,56px);line-height:1.08;letter-spacing:-2px;margin:14px 0 18px}}h2{{font-size:23px;line-height:1.25;letter-spacing:-.5px;margin:8px 0}}p{{color:var(--muted);margin:10px 0}}.notice{{border-left:3px solid var(--gold);background:#fff7e7;padding:12px 18px;margin-bottom:24px;font-size:13px}}.cards{{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}}.card,.panel{{background:white;border:1px solid var(--line);border-radius:12px;padding:22px}}.card strong{{display:block;font-size:36px;line-height:1.4;letter-spacing:-1px}}small{{display:block;font-size:12px;color:var(--muted)}}.panel{{margin-top:24px}}.comparison{{display:grid;grid-template-columns:1fr auto;align-items:center;background:var(--ink);color:white;border-color:var(--ink)}}.comparison p,.comparison .eyebrow,.comparison small{{color:#c3d5d6}}.delta{{font-size:42px;color:var(--gold);font-weight:750;text-align:right}}.wide{{grid-column:1/-1;font-size:13px}}.slice{{display:grid;grid-template-columns:150px 1fr 50px;align-items:center;gap:18px;margin:14px 0;font-size:13px}}.slice b{{text-align:right}}.track{{height:8px;background:#edf0ec;border-radius:6px;overflow:hidden}}.track div{{height:100%;background:var(--green)}}.section-title{{display:flex;align-items:center;justify-content:space-between;margin:32px 0 14px}}.badge{{padding:4px 8px;border-radius:5px;font-size:10px;font-weight:800;letter-spacing:.8px;white-space:nowrap}}.pass{{background:#e3f3e9;color:#075e47}}.fail{{background:#fce6e1;color:#9d3028}}.case{{border:1px solid var(--line);border-radius:8px;background:white;margin:8px 0;overflow:hidden}}summary{{padding:14px;cursor:pointer;display:flex;align-items:center;gap:14px;font-size:13px}}summary b{{flex:1}}.tags{{color:var(--muted);font-size:11px}}.evidence{{padding:6px 22px 20px;border-top:1px solid var(--line)}}pre{{font:12px/1.6 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#f3f5f2;padding:16px;border-radius:8px}}ul{{padding:0;list-style:none}}li{{margin:12px 0;font-size:13px}}li small{{margin-left:56px}}button{{border:1px solid var(--line);background:white;border-radius:6px;padding:7px 12px;color:var(--ink);cursor:pointer}}footer{{border-top:1px solid var(--line);margin-top:36px;padding-top:20px;font-size:12px;color:var(--muted)}}@media(max-width:720px){{main{{padding:24px 16px}}.cards{{grid-template-columns:repeat(2,1fr)}}.tags{{display:none}}.slice{{grid-template-columns:95px 1fr 35px}}.comparison{{grid-template-columns:1fr}}.delta{{text-align:left}}summary{{gap:8px}}}}
</style></head><body><main><header><div class="brand"><span class="mark">A</span>Agent Eval Lab</div><span class="mono">RUN {esc(run['run_id'])}</span></header><section class="hero"><span class="eyebrow">QUALITY / TRAJECTORY / RELIABILITY</span><h1>Evaluate what the<br>agent actually did.</h1><p>{esc(run['adapter'])} · {esc(run['created_at'])} · Framework {esc(run['framework_version'])}</p></section><div class="notice">{"SCRIPTED DEMO — Handcrafted synthetic fixtures, no LLM inference. These scores demonstrate the evaluation harness; they are not production model results." if demo else "LIVE ADAPTER — Scores apply to this curated dataset and configuration. Review failures and validate with representative held-out production data."}</div><section class="cards">{card_html}</section>{compare_html}<section class="panel"><span class="eyebrow">FAILURE LOCALIZATION</span><h2>Performance by slice</h2><p>A case may belong to multiple slices.</p>{slices}</section><div class="section-title"><h2>Case evidence</h2><button id="filter" type="button" aria-pressed="false">Show failures only</button></div>{''.join(rows)}<footer>Dataset SHA-256: <span class="mono">{esc(run['dataset_sha256'])}</span><br>Known successful-call cost: {esc(known_cost)}. Failed/retried attempts may incur unreported cost.<br>Checks use lexical correctness, contracts and trace evidence. Citation presence does not prove factual entailment. Raw answers and tool outputs may contain sensitive data; review before sharing.</footer></main><script>document.getElementById('filter').addEventListener('click',function(){{const active=this.getAttribute('aria-pressed')!=='true';this.setAttribute('aria-pressed',String(active));this.textContent=active?'Show all cases':'Show failures only';document.querySelectorAll('.case').forEach(el=>el.hidden=active&&el.dataset.status==='pass')}});</script></body></html>'''


def write_artifacts(run: dict, directory: str | Path, comparison: dict | None = None):
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    (directory / "run.json").write_text(json.dumps(run, indent=2, ensure_ascii=False), encoding="utf-8")
    (directory / "results.jsonl").write_text("\n".join(json.dumps(row, ensure_ascii=False) for row in run["results"]) + "\n", encoding="utf-8")
    (directory / "report.html").write_text(render_report(run, comparison), encoding="utf-8")
    if comparison:
        (directory / "comparison.json").write_text(json.dumps(comparison, indent=2), encoding="utf-8")
